package academy;
import static org.junit.jupiter.api.Assertions.*;
import java.sql.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;
class RelationalInvariantTest {
  private String database() throws Exception {String url="jdbc:h2:mem:db"+System.nanoTime()+";DB_CLOSE_DELAY=-1";try(Connection c=DriverManager.getConnection(url);Statement s=c.createStatement()){s.execute("create table inventory(sku varchar primary key, available int not null check (available >= 0), version int not null)");s.execute("insert into inventory values ('book',7,0)");s.execute("create table reservation(request_id varchar primary key, sku varchar not null)");}return url;}
  @Test void conditionalUpdateNeverOversells() throws Exception {String url=database();int callers=20;var start=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(callers);List<Future<Integer>> work=new ArrayList<>();for(int i=0;i<callers;i++)work.add(pool.submit(()->{start.await();try(Connection c=DriverManager.getConnection(url);PreparedStatement p=c.prepareStatement("update inventory set available=available-1,version=version+1 where sku='book' and available>0")){return p.executeUpdate();}}));start.countDown();int accepted=0;for(var f:work)accepted+=f.get(5,TimeUnit.SECONDS);pool.shutdownNow();assertEquals(7,accepted);try(Connection c=DriverManager.getConnection(url);Statement s=c.createStatement();ResultSet r=s.executeQuery("select available from inventory where sku='book'")){assertTrue(r.next());assertEquals(0,r.getInt(1));}}
  @Test void staleOptimisticVersionIsDetected() throws Exception {String url=database();try(Connection c=DriverManager.getConnection(url);PreparedStatement p=c.prepareStatement("update inventory set available=?,version=version+1 where sku='book' and version=0")){p.setInt(1,6);assertEquals(1,p.executeUpdate());p.setInt(1,5);assertEquals(0,p.executeUpdate());}}
  @Test void duplicateReservationDoesNotDecrementTwice() throws Exception {String url=database();var start=new CountDownLatch(1);ExecutorService pool=Executors.newFixedThreadPool(2);Callable<Boolean> reserve=()->{start.await();try(Connection c=DriverManager.getConnection(url)){c.setAutoCommit(false);try(PreparedStatement claim=c.prepareStatement("insert into reservation values ('req-42','book')");PreparedStatement decrement=c.prepareStatement("update inventory set available=available-1 where sku='book' and available>0")){claim.executeUpdate();assertEquals(1,decrement.executeUpdate());c.commit();return true;}catch(SQLException duplicate){c.rollback();return false;}}};Future<Boolean>a=pool.submit(reserve),b=pool.submit(reserve);start.countDown();assertNotEquals(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS));pool.shutdownNow();try(Connection c=DriverManager.getConnection(url);Statement s=c.createStatement()){ResultSet stock=s.executeQuery("select available from inventory where sku='book'");stock.next();assertEquals(6,stock.getInt(1));ResultSet rows=s.executeQuery("select count(*) from reservation");rows.next();assertEquals(1,rows.getInt(1));}}
}
